function opportunityFitReason(area: string | undefined, type: string, demonstratedSkills: string[] = []) {
  if (!area) return "Choose a learning direction first. Hana will then compare this opportunity with your demonstrated skills.";
  const relevantSkill = demonstratedSkills.find((skill) => /cyber|network|security|data|python|ai|machine|web|cloud|git|design/i.test(skill) && (new RegExp(skill.replace(/[.*+?^${}()|[\\]\\\\]/g, "\\\\$&"), "i").test(type) || /open-source|internship|work|hackathon|competition/i.test(type)));
  if (relevantSkill) return `This builds on your saved evidence: ${relevantSkill}. Check the official rules before applying.`;
  if (/cyber|ctf|security/i.test(type) && /cyber|security/i.test(area)) return `This matches your ${area} direction and gives you a safe way to practise security skills.`;
  if (/data|ai/i.test(type) && /data|ai|machine/i.test(area)) return `This matches your ${area} direction and gives you a place to explain your technical work.`;
  if (/open-source|internship|work/i.test(type)) return `This can help you practise ${area} in a real project setting when your current skills are ready.`;
  return `This can help you practise ${area} by building and explaining a real project.`;
}

function resourcesForStep(area: string | undefined, step: JourneyStep) {
  const set = resourceSets[area || ""] || resourceSets.default;
  const primary = { label: `Start here · ${step.resource.label}`, url: step.resource.url, note: `Best first stop for ${step.title}. Use this before the alternatives.` };
  const alternatives = [
    { ...set.video, label: `Video lesson · ${step.title}` },
    { ...set.university, label: `University lesson · ${step.title}` },
    { ...set.backup, label: `Backup course · ${step.title}` },
  ];
  return [primary, ...alternatives].filter((resource, index, all) => all.findIndex((item) => item.url === resource.url) === index);
}

